-- generated by tools/gencatalog, do not edit by hand
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE assignments (
    id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    employee_id BIGINT REFERENCES employees(id) NOT NULL,
    org_unit_id BIGINT REFERENCES org_units(id) NOT NULL,
    position_id BIGINT REFERENCES positions(id) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT chk_assignments_period CHECK (end_date IS NULL OR end_date >= start_date),
    CONSTRAINT excl_assignments_employee_period EXCLUDE USING gist (employee_id WITH =, daterange(start_date, end_date, '[]') WITH &&) WHERE (NOT is_deleted)
);

CREATE TABLE assignment_revisions (
    id              BIGINT       PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    assignment_id BIGINT       NOT NULL REFERENCES assignments(id) ON DELETE CASCADE,
    revision_number INTEGER      NOT NULL CHECK (revision_number >= 1),
    change          JSONB        NOT NULL,
    changed_by      UUID         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_assignment_revisions_revision
        UNIQUE (assignment_id, revision_number)
);

CREATE INDEX idx_assignments_employee_id
    ON assignments (employee_id);

CREATE INDEX idx_assignments_org_unit_id
    ON assignments (org_unit_id);

CREATE INDEX idx_assignments_position_id
    ON assignments (position_id);

CREATE INDEX idx_assignments_active
    ON assignments (id)
    WHERE is_deleted = FALSE;

CREATE INDEX idx_assignment_revisions_assignment_id
    ON assignment_revisions (assignment_id);

CREATE INDEX idx_assignment_revisions_covering_agg
    ON assignment_revisions (assignment_id, revision_number DESC)
    INCLUDE (changed_at, changed_by, change);

CREATE INDEX idx_assignment_revisions_changed_at
    ON assignment_revisions (changed_at);

CREATE OR REPLACE VIEW v_expanded_assignment AS
SELECT
    t.id,
    t.employee_id,
    t.org_unit_id,
    t.position_id,
    t.start_date,
    t.end_date,
    t.is_deleted,
    agg.revision,
    agg.last_changer,
    agg.created_at,
    agg.updated_at,
    agg.deleted_at
FROM assignments t
LEFT JOIN (
    SELECT
        assignment_id,
        MAX(revision_number) AS revision,
        MAX(changed_at) AS updated_at,
        (ARRAY_AGG(changed_by ORDER BY revision_number DESC))[1] AS last_changer,
        MIN(changed_at) FILTER (WHERE revision_number = 1) AS created_at,
        MAX(changed_at) FILTER (
            WHERE change @> '[{"path": "/is_deleted", "value": true}]'::jsonb
        ) AS deleted_at
    FROM assignment_revisions
    GROUP BY assignment_id
) agg ON agg.assignment_id = t.id;

COMMENT ON TABLE assignments IS
    'Assignments of employees to units and positions with the period they are in effect. Periods of one employee do not overlap. Stores the current state of each record.';

COMMENT ON TABLE assignment_revisions IS
    'Immutable audit log of changes applied to assignments. Read-only from the application perspective.';

COMMENT ON VIEW v_expanded_assignment IS
    'Read-only view that enriches each assignment with its latest revision number, '
    'last changer UUID, and lifecycle timestamps derived from the revision log.';
